import{_ as e}from"./chunks/waypoints.ByHsBWfB.js";import{_ as a,o,c as n,a2 as i}from"./chunks/framework.eFe5Lsvn.js";const u=JSON.parse('{"title":"Building paths","description":"","frontmatter":{},"headers":[],"relativePath":"app/paths.md","filePath":"app/paths.md"}'),r={name:"app/paths.md"};function s(l,t,h,d,p,g){return o(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="building-paths" tabindex="-1">Building paths <a class="header-anchor" href="#building-paths" aria-label="Permalink to &quot;Building paths&quot;">​</a></h1><p>Switch to <strong>Paths</strong> in the top bar. A project holds many paths; the sidebar lists them. Use the folder button in the <em>Paths</em> header to organize them into folders, and drag paths into folders.</p><p><img src="'+e+'" alt="Waypoints and the waypoint panel"></p><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td>Select</td><td><kbd>V</kbd></td><td>Select or drag. Drag empty space to pan, scroll to zoom.</td></tr><tr><td>Pose</td><td><kbd>W</kbd></td><td>Adds a waypoint with a position <strong>and</strong> a heading (drawn as the robot box with a heading knob).</td></tr><tr><td>Translation</td><td><kbd>T</kbd></td><td>Adds a waypoint with a position only; the robot may face any direction (drawn as a dot).</td></tr><tr><td>Guide</td><td><kbd>G</kbd></td><td>Shapes the route without constraining it (for example, &quot;go left of the hub&quot;).</td></tr></tbody></table><p>New waypoints always go at the <strong>end</strong> of the path. To change the order, drag waypoints in the sidebar list (grab the handle on the left), or use the ↑/↓ buttons. Constraints and markers stay attached to the waypoints they referenced.</p><h2 id="editing-a-waypoint" tabindex="-1">Editing a waypoint <a class="header-anchor" href="#editing-a-waypoint" aria-label="Permalink to &quot;Editing a waypoint&quot;">​</a></h2><p>Drag a pose waypoint&#39;s round knob to set its heading (hold <kbd>⇧</kbd> to snap). Select a waypoint to edit it in the floating panel:</p><ul><li><strong>Pose / Translation / Guide</strong> switches the type.</li><li><strong>Position tolerance</strong> (circle or box) lets the solver end anywhere inside, which often turns an infeasible path into a feasible one.</li><li><strong>Stop here</strong> brings the robot to rest. The first waypoint always stops.</li><li><strong>Split here</strong> lets robot code run the path in pieces and branch between them. See <a href="/Mayhem/lib/splits-and-alliance">Splits and alliance flipping</a>.</li><li><strong>Pose variable</strong> links the waypoint to a <a href="/Mayhem/app/markers#pose-variables">shared pose</a>.</li></ul><h2 id="generating" tabindex="-1">Generating <a class="header-anchor" href="#generating" aria-label="Permalink to &quot;Generating&quot;">​</a></h2><p>Press <strong>Generate</strong> (<kbd>⌘</kbd><kbd>↵</kbd>), or <strong>Generate all</strong> for every path. The solver tries several routes around obstacles in parallel and keeps the fastest. The path is colored by speed and fades when you edit its inputs, until you regenerate.</p><p>To stop, click <strong>Cancel generation</strong> in the top bar. It stops running solves and clears any paths waiting in a <strong>Generate all</strong> batch. Previously generated paths remain available.</p><h3 id="when-generation-fails" tabindex="-1">When generation fails <a class="header-anchor" href="#when-generation-fails" aria-label="Permalink to &quot;When generation fails&quot;">​</a></h3><p>If generation fails, a panel lists what&#39;s wrong (for example, &quot;Waypoint 3 heading conflicts with point-at constraint&quot;) and a red pin marks the spot. Click an issue to jump there.</p><p>If the solver finds a likely conflict while it is still checking other routes, an amber <strong>Likely unsolvable</strong> panel appears early. Click an issue to inspect its location, or click <strong>Stop</strong> in that panel to end generation and keep the diagnosis visible.</p><p>See <a href="/Mayhem/app/troubleshooting">Troubleshooting</a> for the common messages.</p><h2 id="flip-top-↔-bottom" tabindex="-1">Flip top ↔ bottom <a class="header-anchor" href="#flip-top-↔-bottom" aria-label="Permalink to &quot;Flip top ↔ bottom&quot;">​</a></h2><p>Right-click a path and choose <strong>Flip across blue alliance</strong> to mirror it across the field&#39;s long center line (for example, a route over the top bump becomes the same route over the bottom one), or <strong>Duplicate flipped</strong> to keep the original and add the mirrored copy.</p><p>Waypoints, point-at targets and keep-in, keep-out and zone regions are mirrored, then the path is re-solved against the obstacles on that side. Waypoints linked to a pose variable relink to one at the mirrored pose if it exists, otherwise they unlink.</p>',19)])])}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
